package com.citacloud.app.models;
import jakarta.persistence.*;
import java.util.UUID;
@Entity @Table(name="configuracion_empresa_fase2") public class ConfiguracionEmpresaFase2 {
 @Id @Column(name="empresa_id") private UUID empresaId; @Column(name="requiere_aprobacion_citas") private boolean requiereAprobacionCitas; @Column(name="prefijo_factura") private String prefijoFactura="FAC"; @Column(name="siguiente_factura") private int siguienteFactura=1; @Column(name="recordatorios_activos") private boolean recordatoriosActivos=true; @Column(name="notificaciones_activas") private boolean notificacionesActivas=true; @Column(name="unidad_altura") private String unidadAltura="METROS"; @Column(name="unidad_peso") private String unidadPeso="KG"; @Column(name="unidad_temperatura") private String unidadTemperatura="C";
 public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public boolean isRequiereAprobacionCitas(){return requiereAprobacionCitas;} public void setRequiereAprobacionCitas(boolean v){requiereAprobacionCitas=v;} public String getPrefijoFactura(){return prefijoFactura;} public void setPrefijoFactura(String v){prefijoFactura=v;} public int getSiguienteFactura(){return siguienteFactura;} public void setSiguienteFactura(int v){siguienteFactura=v;} public boolean isRecordatoriosActivos(){return recordatoriosActivos;} public void setRecordatoriosActivos(boolean v){recordatoriosActivos=v;} public boolean isNotificacionesActivas(){return notificacionesActivas;} public void setNotificacionesActivas(boolean v){notificacionesActivas=v;} public String getUnidadAltura(){return unidadAltura;} public void setUnidadAltura(String v){unidadAltura=v;} public String getUnidadPeso(){return unidadPeso;} public void setUnidadPeso(String v){unidadPeso=v;} public String getUnidadTemperatura(){return unidadTemperatura;} public void setUnidadTemperatura(String v){unidadTemperatura=v;}
}
